{"kind": "content", "icon": "2️⃣", "head": "पहचानना मुश्किल", "points": ["भारत के मनुष्य को देखकर कोई पहचान नहीं पाता", "यह हिंदू है, मुसलमान है या ईसाई (क्रिस्तान)?", "क्योंकि सबने अपनी-अपनी वेश-भूषा छोड़ दी", "सब एक जैसे अंग्रेज़ी कपड़ों में — अपनी पहचान खो दी"], "say": "दूसरे दोहे का भाव। कवि कहते हैं, आज भारत के किसी मनुष्य को देखकर, कोई पहचान ही नहीं पाता, कि यह हिंदू है, मुसलमान है, या क्रिस्तान, यानी ईसाई। क्यों? क्योंकि सबने, अपनी-अपनी पारंपरिक वेश-भूषा छोड़ दी है। सब, एक जैसे अंग्रेज़ी कपड़े पहनने लगे हैं। ध्यान दीजिए, कवि यहाँ धर्मों में भेद की बात नहीं कर रहे। वे कह रहे हैं, कि भारत के लोगों ने, अपनी भारतीय पहचान ही खो दी है।"},
{"kind": "content", "icon": "3️⃣", "head": "विदेशी पढ़ाई, विदेशी बुद्धि", "points": ["लोगों ने परदेस की विद्या पढ़ी", "उससे उनकी बुद्धि भी विदेशी हो गई", "अब उन्हें परदेस का चाल-चलन ही बहुत अच्छा लगता है", "यानी पढ़ाई ने अपनी जड़ों से काट दिया"], "say": "तीसरे दोहे का भाव। कवि कहते हैं, इन लोगों ने, परदेस की विद्या पढ़ी, यानी अंग्रेज़ी शिक्षा पाई। और उस शिक्षा से, उनकी बुद्धि भी, विदेशी हो गई। अब उन्हें, परदेस का चाल-चलन ही, बहुत अच्छा लगने लगा है। याद कीजिए, गांधी जी ने भी, शिक्षा और संस्कृति वाले पाठ में, यही कहा था, कि जो शिक्षा बच्चे को, अपने घर और गाँव से काट दे, वह अधूरी है। प्रेमघन ने यह बात, गांधी जी से भी पहले कह दी थी।"},
{"kind": "content", "icon": "4️⃣", "head": "देश बन गया विदेश", "points": ["सबने विदेशी ठाट-बाट अपना लिया", "अपना ही देश विदेश जैसा लगने लगा", "इन लोगों में सपने में भी भारतीयता का लेश (ज़रा-सा अंश) नहीं", "ठाट = शान-शौकत · लेश = थोड़ा-सा भी"], "say": "चौथे दोहे का भाव। कवि कहते हैं, सबने विदेशी ठाट-बाट, यानी शान-शौकत अपना ली है। इसके कारण, अपना ही देश, विदेश जैसा लगने लगा है। इन लोगों में, सपने में भी, भारतीयता का लेश, यानी ज़रा-सा अंश भी, दिखाई नहीं देता। कवि का दुख देखिए। वे अपने ही देश में, अजनबी जैसा महसूस कर रहे हैं।"},
{"kind": "eq", "icon": "5️⃣", "head": "भाषा का दुख", "words": "बोलि सकत हिंदी नहीं, अब मिलि हिंदू लोग।\nअंगरेजी भाखन करत, अंगरेजी उपभोग॥", "eq": "लोग आपस में मिलकर अब हिंदी नहीं बोल पाते — अंग्रेज़ी में बात करते हैं, अंग्रेज़ी चीज़ें ही भोगते हैं", "note": "भाखन = भाषण, बोलना · उपभोग = इस्तेमाल", "say": "पाँचवाँ दोहा, भाषा के बारे में है। बोलि सकत हिंदी नहीं, अब मिलि हिंदू लोग। अंगरेजी भाखन करत, अंगरेजी उपभोग। भाखन, यानी बोलना। उपभोग, यानी इस्तेमाल। यहाँ हिंदू लोग का अर्थ है, हिंदुस्तान के लोग। अर्थ है, कवि कहते हैं, भारत के लोग, जब आपस में मिलते हैं, तो अब हिंदी नहीं बोल पाते। वे अंग्रेज़ी में ही बातचीत करते हैं, और अंग्रेज़ी चीज़ों का ही इस्तेमाल करते हैं। सोचिए, दो भारतीय मिलें, और अपनी भाषा में बात न कर सकें, इससे बड़ी विडंबना क्या होगी।"},
{"kind": "table", "icon": "📋", "head": "सब कुछ अंग्रेज़ी", "eq": "छठे दोहे का भाव", "rows": [["क्या-क्या अंग्रेज़ी हो गया", "अर्थ"], ["बाहन", "सवारी, गाड़ी"], ["बसन", "कपड़े"], ["वेष", "पहनावा, रूप"], ["रीति और नीति", "तौर-तरीक़े और नियम"], ["रुचि", "पसंद"], ["गृह", "घर की बनावट-सजावट"]], "say": "छठे दोहे में कवि, एक पूरी सूची देते हैं, कि क्या-क्या अंग्रेज़ी हो गया है। बाहन, यानी सवारी। बसन, यानी कपड़े। वेष, यानी पहनावा। रीति और नीति, यानी तौर-तरीक़े और नियम। रुचि, यानी पसंद। और गृह, यानी घर। कवि कहते हैं, सब कुछ अंग्रेज़ी हो गया है। और ये सारी वस्तुएँ, हमारे देश के विपरीत हैं, यानी हमारे देश की जलवायु और ज़रूरत के, उल्टी हैं।"},
{"kind": "eq", "icon": "7️⃣", "head": "अपने नाम से शर्म", "words": "हिन्दुस्तानी नाम सुनि, अब ये सकुचि लजात।\nभारतीय सब वस्तु ही, सों ये हाय घिनात॥", "eq": "'हिंदुस्तानी' नाम सुनकर ये लोग सकुचाते और लजाते हैं — हाय! भारत की हर वस्तु से इन्हें घिन आती है", "note": "सकुचि = संकोच करके · लजात = शरमाते हैं · घिनात = घृणा करते हैं", "say": "सातवाँ दोहा, सबसे चुभने वाला है। हिन्दुस्तानी नाम सुनि, अब ये सकुचि लजात। भारतीय सब वस्तु ही, सों ये हाय घिनात। सकुचि, यानी संकोच करके। लजात, यानी शरमाते हैं। घिनात, यानी घृणा करते हैं। अर्थ है, कवि कहते हैं, अब ये लोग, हिंदुस्तानी नाम सुनकर ही, सकुचाते और शरमाते हैं। और हाय! भारत की बनी हर वस्तु से, इन्हें घिन आती है। यानी इन्हें, अपने देश का होने में ही, शर्म आती है। कवि के मुँह से हाय निकलता है, यह उनके गहरे दुख की आवाज़ है।"},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "आज भी क्या कुछ लोग अपनी भाषा बोलने या देसी चीज़ इस्तेमाल करने में शर्म महसूस करते हैं?", "a": "हाँ — इसीलिए यह कविता आज भी उतनी ही सच्ची है। अपनी चीज़ों पर गर्व करना सीखें", "pause": 6, "say": "सोचिए। क्या आज भी, कुछ लोग, अपनी भाषा बोलने में, या अपने देश की बनी चीज़ इस्तेमाल करने में, शर्म महसूस करते हैं? ... हाँ, कई बार ऐसा होता है। कोई भोजपुरी या मगही बोलने में झिझकता है, कोई देसी सामान को घटिया समझता है। इसीलिए, सवा सौ साल पुरानी यह कविता, आज भी उतनी ही सच्ची लगती है। हमें अपनी चीज़ों पर, गर्व करना सीखना होगा।"},
{"kind": "content", "icon": "8️⃣", "head": "बाज़ार अंग्रेज़ी माल से भरे", "points": ["देश के नगरों की बनावट (बानक) पूरी अंग्रेज़ी चाल की", "हाट-बाज़ारों में देखो — अंग्रेज़ी माल ही भरा पड़ा है", "देसी माल, देसी कारीगर — कहीं नहीं", "हाट = बाज़ार · बानक = बनावट, रूप"], "say": "आठवें दोहे का भाव। कवि कहते हैं, देश के नगरों की बनावट, पूरी तरह अंग्रेज़ी चाल की हो गई है। और हाट-बाज़ारों में जाकर देखो, तो वहाँ अंग्रेज़ी माल ही, भरा पड़ा है। देसी माल, और देसी कारीगर की बनाई चीज़, कहीं दिखती ही नहीं। याद कीजिए, हमारी कहानी का मेला। विदेशी खिलौनों की दुकान पर भीड़, और रामू काका की दुकान ख़ाली।"},
{"kind": "eq", "icon": "9️⃣", "head": "तीखा व्यंग्य: ढीली धोती", "words": "जिनसों सम्हल सकत नहिं, तनक धोती ढीली-ढाली।\nदेस प्रबंध करिहिंगे वे, यह कैसी खाम ख्याली॥", "eq": "जिनसे अपनी ढीली धोती तक नहीं सँभलती, वे देश का प्रबंध करेंगे — यह कैसा कच्चा ख़याल (भ्रम) है!", "note": "तनक = ज़रा-सी · प्रबंध = इंतज़ाम, शासन · खाम ख्याली = कच्चा ख़याल, कोरी कल्पना", "say": "नौवें छंद में, कवि बहुत तीखा व्यंग्य करते हैं। जिनसों सम्हल सकत नहिं, तनक धोती ढीली-ढाली। देस प्रबंध करिहिंगे वे, यह कैसी खाम ख्याली। तनक, यानी ज़रा-सी। प्रबंध, यानी इंतज़ाम, शासन। खाम ख्याली, यानी कच्चा ख़याल, कोरी कल्पना। अर्थ है, कवि कहते हैं, जिन लोगों से, अपनी ज़रा-सी ढीली-ढाली धोती तक नहीं सँभलती, वे देश का प्रबंध करेंगे, देश को चलाएँगे, यह कैसी कोरी कल्पना है! यानी जो अपना पहनावा, अपनी संस्कृति तक नहीं सँभाल पाए, वे देश को क्या सँभालेंगे।"},
{"kind": "content", "icon": "🔟", "head": "ग़ुलामी की चाह", "points": ["चारों ओर, हर वर्ग में दास-वृत्ति (नौकरी-ग़ुलामी) की चाह बढ़ रही", "लोग अंग्रेज़ों की ख़ुशामद और झूठी प्रशंसा करते हैं", "जैसे डफ़ बजाकर गुणगान करने वाले डफाली बन गए हों", "दास-वृत्ति = ग़ुलामी की आदत · ख़ुशामद = चापलूसी"], "say": "अंतिम छंद का भाव। कवि कहते हैं, चारों दिशाओं में, समाज के हर वर्ग में, दास-वृत्ति की चाह बढ़ती जा रही है। दास-वृत्ति, यानी ग़ुलामी की आदत, दूसरों की नौकरी-चाकरी की इच्छा। लोग, अंग्रेज़ों की ख़ुशामद, यानी चापलूसी करते हैं, उनकी झूठी प्रशंसा करते हैं। ऐसा लगता है, मानो वे डफाली बन गए हों। डफाली, वे होते हैं, जो डफ़ बजाकर, दूसरों का गुणगान करते फिरते हैं। यानी लोग, अपना स्वाभिमान भूलकर, बस मालिकों को ख़ुश करने में लगे हैं।"},
{"kind": "table", "icon": "📋", "head": "कविता का भाव — एक नज़र में", "eq": "कवि की शिकायतें", "rows": [["बात", "कवि क्या कहते हैं"], ["वस्तुएँ, चाल-ढाल", "सब विदेशी, भारतीयता ग़ायब"], ["पहचान", "कोई पहचान नहीं पाता कि कौन क्या है"], ["शिक्षा", "विदेशी विद्या से बुद्धि भी विदेशी"], ["भाषा", "हिंदी नहीं बोल पाते, अंग्रेज़ी ही"], ["मन", "'हिंदुस्तानी' नाम से शर्म, देसी चीज़ से घिन"], ["बाज़ार", "अंग्रेज़ी माल से भरे"], ["स्वभाव", "दास-वृत्ति, ख़ुशामद"]], "say": "पूरी कविता का भाव, एक नज़र में। वस्तुएँ और चाल-ढाल, सब विदेशी हो गए, भारतीयता ग़ायब है। पहचान ऐसी खोई, कि कोई पहचान नहीं पाता। विदेशी विद्या से, बुद्धि भी विदेशी हो गई। लोग हिंदी नहीं बोल पाते, अंग्रेज़ी ही बोलते हैं। हिंदुस्तानी नाम से शर्म, और देसी चीज़ से घिन आती है। बाज़ार, अंग्रेज़ी माल से भरे हैं। और स्वभाव में, दास-वृत्ति और ख़ुशामद आ गई है।"},
{"kind": "eq", "icon": "💡", "head": "कवि का असली संदेश", "words": "कवि सिर्फ़ शिकायत नहीं कर रहे — वे जगा रहे हैं", "eq": "अपनी भाषा, अपना वेश, अपनी वस्तु अपनाओ — तभी देश स्वाधीन और मज़बूत होगा", "note": "विदेशी ज्ञान से बैर नहीं — पर अपनी पहचान खोना ग़ुलामी है", "say": "अब कवि का असली संदेश समझिए। कवि केवल शिकायत नहीं कर रहे, वे देशवासियों को जगा रहे हैं। उनका संदेश है, अपनी भाषा अपनाओ, अपना वेश अपनाओ, अपने देश की बनी वस्तु अपनाओ। तभी देश, सचमुच स्वाधीन और मज़बूत होगा। ध्यान दीजिए, कवि को, बाहर के ज्ञान से बैर नहीं है। पर नक़ल करते-करते, अपनी पहचान ही खो देना, यह मन की ग़ुलामी है। और मन की ग़ुलामी, शरीर की ग़ुलामी से भी बुरी होती है।"},
{"kind": "content", "icon": "✒️", "head": "भाषा और काव्य-सौंदर्य", "points": ["भाषा: ब्रजभाषा, जिसमें खड़ी बोली और उर्दू के शब्द भी (ख़ुशामद, खाम ख्याली)", "छंद: दोहा", "शैली: व्यंग्यात्मक — हँसी के पीछे गहरा दुख", "अनुप्रास: 'रति रीत', 'बाहन बसन', 'चाह चहुँ'", "उत्प्रेक्षा: 'मानहुँ बने डफाली' (मानहुँ = मानो)", "भाव: देश-प्रेम, राष्ट्रीय चेतना"], "say": "अब काव्य-सौंदर्य। कविता की भाषा ब्रजभाषा है, जिसमें खड़ी बोली, और उर्दू के शब्द भी मिले हैं, जैसे ख़ुशामद, और खाम ख्याली। छंद है, दोहा। शैली व्यंग्यात्मक है, यानी कवि चुटकी लेते हैं, पर उस हँसी के पीछे, गहरा दुख है। अलंकार देखिए। रति रीत, बाहन बसन, और चाह चहुँ में, एक ही अक्षर की आवृत्ति है, यह अनुप्रास है। मानहुँ बने डफाली, यहाँ मानहुँ, यानी मानो शब्द से, संभावना जताई गई है, इसलिए यह उत्प्रेक्षा अलंकार है। और कविता का मूल भाव है, देश-प्रेम और राष्ट्रीय चेतना।"},
{"kind": "table", "icon": "📋", "head": "कठिन शब्द", "eq": "शब्द और अर्थ", "rows": [["शब्द", "अर्थ"], ["लखात", "दिखाई देता है"], ["क्रिस्तान", "ईसाई"], ["लेस", "ज़रा-सा अंश"], ["भाखन", "बोलना, भाषण"], ["बसन", "कपड़े"], ["घिनात", "घृणा करते हैं"], ["हाट", "बाज़ार"], ["खाम ख्याली", "कोरी कल्पना"], ["डफाली", "डफ़ बजाकर गुणगान करने वाला"]], "say": "कुछ कठिन शब्द। लखात, दिखाई देता है। क्रिस्तान, ईसाई। लेस, ज़रा-सा अंश। भाखन, बोलना। बसन, कपड़े। घिनात, घृणा करते हैं। हाट, बाज़ार। खाम ख्याली, कोरी कल्पना। और डफाली, डफ़ बजाकर गुणगान करने वाला।"},
{"kind": "content", "icon": "🌾", "head": "बिहार से जुड़ाव: हमारा स्वदेशी", "points": ["भागलपुर का तसर सिल्क — 'सिल्क सिटी'", "मधुबनी की मिथिला पेंटिंग, दुनिया भर में प्रसिद्ध", "मधुबनी-पूर्णिया की खादी · सिक्की घास की कला · मंजूषा कला", "मखाना, शाही लीची, जर्दालू आम, कतरनी चावल — बिहार की पहचान (GI टैग)", "चंपारण से गांधी जी ने चरखे और खादी का संदेश फैलाया"], "say": "बिहार के पास, अपना बहुत सुंदर स्वदेशी है। भागलपुर का तसर सिल्क, जिसके कारण उसे सिल्क सिटी कहते हैं। मधुबनी की मिथिला पेंटिंग, जो दुनिया भर में प्रसिद्ध है। मधुबनी और पूर्णिया की खादी। सिक्की घास से बनी सुंदर चीज़ें, और भागलपुर की मंजूषा कला। खाने में, मिथिला का मखाना, मुज़फ़्फ़रपुर की शाही लीची, भागलपुर का जर्दालू आम, और कतरनी चावल, इन सबको बिहार की ख़ास पहचान के रूप में, जी आई टैग मिला है। और याद रखिए, इसी बिहार के चंपारण से, गांधी जी ने, चरखे और खादी का संदेश, पूरे देश में फैलाया था।"},
{"kind": "list", "icon": "📝", "head": "सार", "points": ["कवि: बदरीनारायण चौधरी 'प्रेमघन' (1855–1923), भारतेंदु युग", "कविता: दोहों में · ग़ुलाम भारत में विदेशी नक़ल पर व्यंग्य", "वस्तु, वेश, भाषा, बाज़ार — सब अंग्रेज़ी; भारतीयता ग़ायब", "'हिंदुस्तानी' नाम से शर्म, दास-वृत्ति, ख़ुशामद", "संदेश: स्वदेशी अपनाओ — अपनी भाषा, वेश, वस्तु पर गर्व"], "say": "आज का सार। एक, कवि बदरीनारायण चौधरी प्रेमघन हैं, जो भारतेंदु युग के कवि थे। दो, यह कविता दोहों में है, और ग़ुलाम भारत में, विदेशी नक़ल पर व्यंग्य करती है। तीन, कवि कहते हैं, कि वस्तु, वेश, भाषा, बाज़ार, सब अंग्रेज़ी हो गए, और भारतीयता ग़ायब हो गई। चार, लोगों को हिंदुस्तानी नाम से शर्म आती है, और उनमें दास-वृत्ति और ख़ुशामद की आदत आ गई है। पाँच, कवि का संदेश है, स्वदेशी अपनाओ, अपनी भाषा, वेश और वस्तु पर गर्व करो।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 1", "q": "'स्वदेशी' कविता के कवि कौन हैं? वे किस युग के कवि हैं?", "a": "बदरीनारायण चौधरी 'प्रेमघन' · भारतेंदु युग", "pause": 4, "say": "अब अभ्यास। वीडियो रोककर उत्तर सोचिए। पहला, स्वदेशी कविता के कवि कौन हैं, और वे किस युग के हैं? ... बदरीनारायण चौधरी प्रेमघन। भारतेंदु युग के।"},
